const input = $input.first().json;
const body = input.body || input;

// Support Contact Form 7, WPForms, Gravity Forms
const formData = {
  email: body.email || body.your_email || body['your-email'] || body.field_email,
  first_name: body.first_name || body.your_name?.split(' ')[0] || body['your-name']?.split(' ')[0] || body.field_name?.split(' ')[0] || '',
  last_name: body.last_name || body.your_name?.split(' ').slice(1).join(' ') || '',
  company: body.company || body.your_company || body.field_company || '',
  phone: body.phone || body.your_phone || body['your-phone'] || body.field_phone || '',
  message: body.message || body.your_message || body['your-message'] || body.field_message || '',
  form_name: body.form_name || body._wpcf7 || body.form_id || 'unknown',
  page_url: body.page_url || body.referrer || '',
  source: 'wordpress',
  utm_source: body.utm_source || '',
  utm_medium: body.utm_medium || '',
  utm_campaign: body.utm_campaign || '',
  client_id: body.client_id
};

if (!formData.email) return [{ json: { error: true, message: 'No email found' } }];

return [{ json: formData }];

const input = $input.first().json;
const body = input.body || input;

// Track page view for known contacts (via cookie/email)
const email = body.email || body.visitor_email;
if (!email) return [{ json: { tracked: false } }];

return [{ json: {
  email: email,
  page_url: body.page_url || body.url || '',
  page_title: body.page_title || body.title || '',
  referrer: body.referrer || '',
  time_on_page: body.time_on_page || 0,
  scroll_depth: body.scroll_depth || 0
}}];
